SELECT p.gender, i.intime, i.los, d.icd_code, COUNT(p.subject_id) AS patient_count, SUM(i.los) / COUNT(p.subject_id) AS avg_los, cume_dist() OVER (PARTITION BY d.icd_code ORDER BY i.intime) AS quartile FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN diagnoses_icd d ON i.hadm_id = d.hadm_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM i.intime) BETWEEN 2019 AND 2020 AND d.icd_code IN ('G418', 'G419') AND i.first_careunit = 'ICU' AND i.hadm_id IN (SELECT hadm_id FROM admissions WHERE admission_type = 'UPPER GI BLEEDING') AND i.intime <= i.dischtime + interval '72 hours' GROUP BY p.gender, i.intime, i.los, d.icd_code, quartile ORDER BY quartile, patient_count NULLS LAST;